"use strict";(self.webpackChunkstrapi_docs=self.webpackChunkstrapi_docs||[]).push([[43099],{12511:e=>{e.exports=JSON.parse('{"tag":{"label":"plugins development","permalink":"/tags/plugins-development","allTagsPath":"/tags","count":26,"items":[{"id":"cms/plugins-development/admin-hooks","title":"Admin hooks","description":"Create and register hooks in Strapi plugins to let other plugins add personalized behavior to your application.","permalink":"/cms/plugins-development/admin-hooks"},{"id":"cms/plugins-development/admin-injection-zones","title":"Admin injection zones","description":"Extend and customize the Strapi admin panel by injecting React components into predefined or custom injection zones.","permalink":"/cms/plugins-development/admin-injection-zones"},{"id":"cms/plugins-development/admin-localization","title":"Admin localization","description":"Provide translations for your Strapi plugin\'s admin panel interface using registerTrads and react-intl.","permalink":"/cms/plugins-development/admin-localization"},{"id":"cms/plugins-development/admin-navigation-settings","title":"Admin navigation & settings","description":"Add menu links, create settings sections, and configure settings links for your Strapi plugin in the admin panel.","permalink":"/cms/plugins-development/admin-navigation-settings"},{"id":"cms/plugins-development/admin-panel-api","title":"Admin Panel API overview","description":"Overview of the Admin Panel API for Strapi plugins, with entry file, lifecycle hooks, and available actions for customizing the admin panel UI.","permalink":"/cms/plugins-development/admin-panel-api"},{"id":"cms/plugins-development/content-manager-apis","title":"Content Manager APIs","description":"The Content Manager APIs reference lists the APIs available to plugins for adding actions and options to the Content Manager List view and Edit view.","permalink":"/cms/plugins-development/content-manager-apis"},{"id":"cms/plugins-development/developing-plugins","title":"Developing plugins","description":"Generation introduction about Strapi plugins development","permalink":"/cms/plugins-development/developing-plugins"},{"id":"cms/migration/v4-to-v5/additional-resources/helper-plugin","title":"Helper-plugin migration reference","description":"Learn how to migrate your Strapi plugins and applications to not use the `helper-plugin` package.","permalink":"/cms/migration/v4-to-v5/additional-resources/helper-plugin"},{"id":"cms/migration/v4-to-v5/breaking-changes/helper-plugin-deprecated","title":"helper-plugin removed","description":"In Strapi 5, the `helper-plugin` is removed. A whole migration reference is available for plugin developers, and codemods will automatically handle some changes.","permalink":"/cms/migration/v4-to-v5/breaking-changes/helper-plugin-deprecated"},{"id":"cms/plugins-development/guides/store-and-access-data","title":"How to store and access data from a Strapi plugin","description":"Learn how to store and access data from a Strapi plugin","permalink":"/cms/plugins-development/guides/store-and-access-data"},{"id":"cms/migration/v4-to-v5/breaking-changes/license-only","title":"lockIcon replaced by licenseOnly","description":"In Strapi 5, the lockIcon property is replaced by licenseOnly, which affects how the addMenuLink(), addSettingsLink(), and addSettingsLinks() methods from the Admin Panel API work.","permalink":"/cms/migration/v4-to-v5/breaking-changes/license-only"},{"id":"cms/plugins-development/create-a-plugin","title":"Plugin creation & setup","description":"Learn how to use the Plugin SDK to build and publish a Strapi plugin","permalink":"/cms/plugins-development/create-a-plugin"},{"id":"cms/plugins-development/plugin-sdk","title":"Plugin SDK reference","description":"Reference documentation for Strapi\'s Plugin SDK commands","permalink":"/cms/plugins-development/plugin-sdk"},{"id":"cms/plugins-development/plugin-structure","title":"Plugin structure","description":"Learn more about the structure of a Strapi plugin","permalink":"/cms/plugins-development/plugin-structure"},{"id":"cms/plugins-development/plugins-extension","title":"Plugins extension","description":"Existing plugins can be overriden by placing code in /src/extensions or using global register/bootstrap hooks. Instructions in this documentation cover reshaping plugin content-type schemas or server logic \u2014 altough upstream updates may break extensions.","permalink":"/cms/plugins-development/plugins-extension"},{"id":"cms/migration/v4-to-v5/additional-resources/plugins-migration","title":"Plugins upgrade summary","description":"The present page is intended to be used as a short summary of everything to consider if you are a plugin developer upgrading your plugin from Strapi v4 to Strapi 5. The page quickly describes the changes affecting plugins and links to additional resources where necessary.","permalink":"/cms/migration/v4-to-v5/additional-resources/plugins-migration"},{"id":"cms/plugins-development/admin-redux-store","title":"Redux store & reducers","description":"Add custom reducers, read state, dispatch actions, and subscribe to changes in Strapi\'s admin panel Redux store from your plugin.","permalink":"/cms/plugins-development/admin-redux-store"},{"id":"cms/plugins-development/server-api","title":"Server API for plugins","description":"Overview of the Strapi Server API for plugins, with entry file, lifecycle hooks, routes, controllers, services, policies, middlewares, and configuration.","permalink":"/cms/plugins-development/server-api"},{"id":"cms/plugins-development/server-configuration","title":"Server configuration","description":"Define default plugin options, validate user-provided values, and read plugin configuration at runtime.","permalink":"/cms/plugins-development/server-configuration"},{"id":"cms/plugins-development/server-content-types","title":"Server content-types","description":"Declare and register content-types in a Strapi plugin and access them at runtime through the Document Service API.","permalink":"/cms/plugins-development/server-content-types"},{"id":"cms/plugins-development/server-controllers-services","title":"Server controllers & services","description":"Handle HTTP requests in plugin controllers and organize reusable business logic in plugin services.","permalink":"/cms/plugins-development/server-controllers-services"},{"id":"cms/plugins-development/server-getters-usage","title":"Server getters & usage","description":"Access and reuse plugin controllers, services, policies, and other server resources using top-level and global getters.","permalink":"/cms/plugins-development/server-getters-usage"},{"id":"cms/plugins-development/server-lifecycle","title":"Server lifecycle","description":"Control when plugin server logic runs with register, bootstrap, and destroy lifecycle hooks.","permalink":"/cms/plugins-development/server-lifecycle"},{"id":"cms/plugins-development/server-policies-middlewares","title":"Server policies & middlewares","description":"Guard plugin routes with policies and intercept requests with middlewares in the Strapi plugin Server API.","permalink":"/cms/plugins-development/server-policies-middlewares"},{"id":"cms/plugins-development/server-routes","title":"Server routes","description":"Expose plugin endpoints as Content API or admin routes, with full control over auth, policies, and route configuration.","permalink":"/cms/plugins-development/server-routes"},{"id":"cms/typescript/development","title":"TypeScript development","description":"Learn more about TypeScript usage with Strapi 5","permalink":"/cms/typescript/development"}],"unlisted":false}}')}}]);